function Require([bool]$ok, [string]$message) { if (-not $ok) { throw $message } }
function Split-TopLevel([string]$text) { $out = [System.Collections.Generic.List[string]]::new(); $quote = $false; $depth = 0; $start = 0; for ($i = 0; $i -lt $text.Length; $i++) { $c = $text[$i]; if ($c -eq "'" -and ($i -eq 0 -or $text[$i-1] -ne '\')) { $quote = -not $quote }; if (-not $quote -and $c -eq '(') { $depth++ } elseif (-not $quote -and $c -eq ')') { $depth-- } elseif (-not $quote -and $depth -eq 0 -and $c -eq ',') { $out.Add($text.Substring($start,$i-$start).Trim()); $start = $i + 1 } }; $out.Add($text.Substring($start).Trim()); return ,$out.ToArray() }
function Get-Tuples([string]$text) { $out = [System.Collections.Generic.List[object]]::new(); $quote = $false; $depth = 0; $start = -1; for ($i = 0; $i -lt $text.Length; $i++) { $c = $text[$i]; if ($c -eq "'" -and ($i -eq 0 -or $text[$i-1] -ne '\')) { $quote = -not $quote }; if (-not $quote -and $c -eq '(') { if ($depth -eq 0) { $start = $i + 1 }; $depth++ } elseif (-not $quote -and $c -eq ')') { $depth--; if ($depth -eq 0) { $out.Add((Split-TopLevel $text.Substring($start,$i-$start))) } } }; return ,$out.ToArray() }
function Get-InsertRows([string]$table) { $rows = [System.Collections.Generic.List[object]]::new(); $pattern = '(?is)INSERT\s+INTO\s+`' + [regex]::Escape($table) + '`\s*\((.*?)\)\s*VALUES\s*(.*?);'; $rx = [regex]::new($pattern); foreach ($m in $rx.Matches($sql)) { foreach ($row in (Get-Tuples $m.Groups[2].Value)) { $rows.Add($row) } }; return ,$rows.ToArray() }
function Unquote([string]$value) { return $value.Trim().Trim("'") }

